const RIYADH = new Date(Date.now() + 3 * 60 * 60 * 1000);
const date = RIYADH.toISOString().slice(0, 10);
const dow = RIYADH.getUTCDay();
const PLAN = {
  0: { day: 'الأحد', pillar: 'بزنس', series: 'لو عندي ___ اليوم', cta_stage: 'تأهيل', production_mode: 'صوت + شاشة' },
  1: { day: 'الاثنين', pillar: 'انتشار', series: 'عطيناه وظيفة', cta_stage: 'وعي', production_mode: 'بدون ظهور' },
  2: { day: 'الثلاثاء', pillar: 'بزنس', series: 'قبل ← بعد', cta_stage: 'تأهيل', production_mode: 'صوت + شاشة' },
  3: { day: 'الأربعاء', pillar: 'بزنس', series: 'الحلقة — الدخل', cta_stage: 'قائمة', production_mode: 'ظهور على الكاميرا' },
  4: { day: 'الخميس', pillar: 'تعليمي', series: 'خطوة بخطوة', cta_stage: 'حفظ', production_mode: 'صوت + شاشة' },
  5: { day: 'الجمعة', pillar: 'انتشار', series: 'هل نقدر نخليه يسوّيها؟', cta_stage: 'وعي', production_mode: 'بدون ظهور' },
  6: { day: 'السبت', pillar: 'انتشار', series: 'هل نقدر نخليه يسوّيها؟', cta_stage: 'وعي', production_mode: 'ظهور على الكاميرا' }
};
const p = PLAN[dow];
const slot = { date: date, weekday: p.day, pillar: p.pillar, series: p.series, cta_stage: p.cta_stage, production_mode: p.production_mode, linkedin_day: dow === 0 || dow === 1 || dow === 2 };
const ideas = $('قراءة بنك الأفكار').all().map(i => i.json).filter(r => r && r.id);
const posts = $input.all().map(i => i.json).filter(r => r && r.post_id);
const forced = String($('طلب موعد اليوم').first().json.query && $('طلب موعد اليوم').first().json.query.idea || '').trim();
const usable = ideas.filter(r => { const s = String(r.status || 'new').trim(); return s !== 'used' && s !== 'rejected' && s !== 'hold'; });
const score = (r) => {
  let v = Number(r.score) || 3;
  if (String(r.status).trim() === 'approved') { v += 10; }
  if (String(r.pillar).trim() === slot.pillar) { v += 4; }
  if (String(r.series).trim() === slot.series) { v += 3; }
  return v;
};
let chosen = null;
if (forced) { chosen = ideas.find(r => String(r.id).trim() === forced) || null; }
else if (usable.length) { chosen = usable.slice().sort((a, b) => score(b) - score(a))[0]; }
const counts = { approved: 0, 'new': 0, hold: 0, rejected: 0, used: 0 };
for (const r of ideas) { const s = String(r.status || 'new').trim(); if (counts[s] !== undefined) { counts[s]++; } }
return [{ json: {
  slot: slot,
  idea: chosen,
  recent: posts.slice(-14).map(p => ({ title: p.title, hook: p.hook })),
  bank_total: ideas.length,
  approved_count: counts.approved,
  new_count: counts['new'],
  picked_because: chosen ? (forced ? 'محددة يدويًا' : 'الأعلى ملاءمة لركيزة اليوم') : 'لا فكرة صالحة'
} }];

const body = $input.first().json.body || {};
const pkg = body.package || {};
const slot = body.slot || {};
const BANNED = ['ثورة','سيقضي على وظيفتك','بيأخذ وظيفتك','ياخذ وظيفتك','أسرار','ربح سريع','دخل بدون مجهود','ستغيّر حياتك','راح تتغير حياتك','أفضل ١٠ أدوات','أفضل 10 أدوات','مجانًا ١٠٠٪','الكل لازم يتعلم','لا تفوّت','خرافي','جنوني','مذهل'];
const SAUDI = ['خطاب','واتساب','فاتورة','فواتير','مناقصة','مناقصات','إجازة','دوام','سيرة ذاتية','سير ذاتية','سيَر','عرض سعر','موظف','الرياض','السعودي','راتب','رواتب'];
const LIMITS = { tiktok: 300, instagram: 400, snapchat: 300, linkedin: 1300, x: 280 };
const caps = pkg.captions || {};
const vid = pkg.video || {};
const blob = JSON.stringify(pkg);
const checks = [];
const add = (id, name, passed, note) => checks.push({ id: id, name: name, passed: passed, note: note || '' });
const hits = BANNED.filter(w => blob.indexOf(w) !== -1);
add(1, 'الكلمات المحظورة', hits.length === 0, hits.join('، '));
const NUMW = new Set(["واحد","واحده","اثنين","اثنان","ثنتين","ثلاث","ثلاثه","ثلاثين","ثلاثون","اربع","اربعه","اربعين","اربعون","خمس","خمسه","خمسين","خمسون","ست","سته","ستين","ستون","سبع","سبعه","سبعين","سبعون","ثمان","ثمانيه","ثمانين","ثمانون","تسع","تسعه","تسعين","تسعون","عشر","عشره","عشرين","عشرون","مئه","مايه","مئتين","الف","الفين","نصف","ربع","ثلث","عشرات","مئات","الاف"]);
const arNorm = (x) => String(x).replace(/[\u064B-\u0652\u0640]/g, "").replace(/[\u0623\u0625\u0622]/g, "\u0627").replace(/\u0629/g, "\u0647").replace(/\u0649/g, "\u064A");
const scriptTxt = String(vid.script || "");
const hasDigit = /[0-9\u0660-\u0669]/.test(scriptTxt);
const hasWordNum = arNorm(scriptTxt).split(/[^\u0621-\u064A]+/).some(w => NUMW.has(w));
const hasNum = hasDigit || hasWordNum;
add(2, 'الرقم في النص الصوتي', hasNum, hasNum ? '' : 'لا يوجد رقم ملموس — لا أرقامًا ولا كلمات عدد');
const verdict = String(vid.verdict || '').trim();
add(3, 'الحكم الصريح', verdict.length > 0, verdict ? '' : 'لا يوجد حكم');
const saudi = SAUDI.some(w => blob.indexOf(w) !== -1);
add(4, 'السياق السعودي', saudi, saudi ? '' : 'لا يوجد مثال سعودي ملموس');
const fear = /(ياخذ|يأخذ|تخسر|بتفقد) وظيفت|يستبدل(ك| الموظف)/.test(blob);
add(5, 'التخويف من فقدان الوظيفة', !fear, fear ? 'وُجد إيحاء بفقدان الوظيفة' : '');
const hooks = vid.hooks || [];
const longHooks = hooks.filter(h => String(h).trim().split(/\s+/).length > 12);
add(6, 'طول الخطّاف', hooks.length === 3 && longHooks.length === 0, longHooks.join(' | '));
const noCta = Object.keys(caps).filter(k => !String((caps[k] && caps[k].cta) || '').trim());
add(7, 'وجود CTA', noCta.length === 0, noCta.join('، '));
const chip = String((vid.result && vid.result.chip) || '');
add(8, 'رقاقة النتيجة', /[0-9\u0660-\u0669]/.test(chip), chip ? '' : 'رقاقة الوقت فارغة');
const tooLong = Object.keys(LIMITS).filter(k => String((caps[k] && caps[k].text) || '').length > LIMITS[k]);
const ytTitle = String((caps.youtube_shorts && caps.youtube_shorts.title) || '');
if (ytTitle.length > 100) { tooLong.push('youtube_shorts.title'); }
add(9, 'حدود الطول', tooLong.length === 0, tooLong.join('، '));
const cover = String((pkg.visual && pkg.visual.cover_text) || '').trim();
const coverWords = cover ? cover.split(/\s+/).length : 0;
add(10, 'نص الغلاف أربع كلمات كحد أقصى', coverWords > 0 && coverWords <= 4, cover);
const failed = checks.filter(c => !c.passed);
const status = failed.length === 0 ? 'pass' : 'fail';
const postId = 'POST-' + String(slot.date || '').replace(/-/g, '');
const scenes = (vid.scenes || []).map(s => s.t + ' · ' + s.action + ' — ' + s.on_screen).join('\n');
let msg = '';
if (status === 'pass') {
  msg += '🎬 حزمة ' + slot.date + ' · ' + slot.weekday + '\n' + slot.pillar + ' · ' + slot.series + '\n';
  msg += 'من الفكرة: ' + (body.idea_id || '') + '\n\n';
  msg += '📌 ' + (pkg.meta && pkg.meta.title || '') + '\n\n';
  msg += '🎣 الخطّافات:\n' + hooks.map((h, i) => (i + 1) + '. ' + h).join('\n') + '\n\n';
  msg += '⏱ ' + chip + '\n⚖️ ' + verdict + '\n\n';
  msg += '🎙 النص الصوتي:\n' + (vid.script || '') + '\n\n';
  msg += '🎞 المشاهد:\n' + scenes + '\n\n';
  msg += '🖼 الغلاف: ' + cover + ' | الرقم: ' + ((pkg.visual && pkg.visual.cover_number) || '');
} else {
  msg = '⚠️ حزمة ' + slot.date + ' لم تجتز الحارس\n\n' + failed.map(c => '❌ ' + c.name + (c.note ? ' — ' + c.note : '')).join('\n');
}
const capMsg = ['📱 كابشنات ' + slot.date,
  '── تيك توك ──\n' + ((caps.tiktok && caps.tiktok.text) || '') + '\n' + (((caps.tiktok && caps.tiktok.hashtags) || []).join(' ')),
  '── إنستقرام ──\n' + ((caps.instagram && caps.instagram.text) || '') + '\n' + (((caps.instagram && caps.instagram.hashtags) || []).join(' ')),
  '── يوتيوب شورتس ──\n' + ytTitle + '\n' + ((caps.youtube_shorts && caps.youtube_shorts.text) || ''),
  '── سناب ──\n' + ((caps.snapchat && caps.snapchat.text) || ''),
  '── إكس ──\n' + ((caps.x && caps.x.text) || '')].join('\n\n');
const liMsg = '💼 لينكدإن ' + slot.date + '\n\n' + ((caps.linkedin && caps.linkedin.text) || '') + '\n\n' + (((caps.linkedin && caps.linkedin.hashtags) || []).join(' ')) + '\n\n── EN ──\n' + ((caps.linkedin && caps.linkedin.en_version) || '');
return [{ json: {
  guard_status: status, checks: checks, failed_count: failed.length,
  post_id: postId, idea_id: body.idea_id || '', slot: slot, package: pkg,
  msg_main: msg.slice(0, 4000), msg_caps: capMsg.slice(0, 4000), msg_li: liMsg.slice(0, 4000),
  row: {
    post_id: postId, date: slot.date || '', day_index: '', pillar: slot.pillar || '', series: slot.series || '',
    title: (pkg.meta && pkg.meta.title) || '', hook: hooks[0] || '', chip: chip, verdict: verdict,
    idea_id: body.idea_id || '', platforms: 'تيك توك، إنستقرام، شورتس، سناب، لينكدإن، إكس',
    status: 'جاهز للتصوير', payload: JSON.stringify(pkg).slice(0, 40000)
  }
} }];
